import{_ as t,o,c as a,a2 as r}from"./chunks/framework.mrTIYZc5.js";const u=JSON.parse('{"title":"Docker Sponsored Open Source (DSOS) Application","description":"","frontmatter":{},"headers":[],"relativePath":"cncf/DSOS_APPLICATION.md","filePath":"cncf/DSOS_APPLICATION.md"}'),i={name:"cncf/DSOS_APPLICATION.md"};function s(n,e,c,l,h,d){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="docker-sponsored-open-source-dsos-application" tabindex="-1">Docker Sponsored Open Source (DSOS) Application <a class="header-anchor" href="#docker-sponsored-open-source-dsos-application" aria-label="Permalink to &quot;Docker Sponsored Open Source (DSOS) Application&quot;">​</a></h1><h2 id="project-name" tabindex="-1">Project Name <a class="header-anchor" href="#project-name" aria-label="Permalink to &quot;Project Name&quot;">​</a></h2><p>Docker Secret Operator (DSO)</p><h2 id="project-description" tabindex="-1">Project Description <a class="header-anchor" href="#project-description" aria-label="Permalink to &quot;Project Description&quot;">​</a></h2><p>DSO is a secret management agent for Docker. It connects your Docker containers to cloud secret providers like AWS Secrets Manager, Azure Key Vault, and HashiCorp Vault, and keeps the secrets in sync automatically.</p><p>Here&#39;s the simplest way to explain it: you define which secrets your containers need in a YAML file, and DSO fetches them at runtime and injects them into the container&#39;s environment. When a secret changes upstream, DSO detects the change and updates the running containers — without you doing anything.</p><p>It ships as a native Docker CLI plugin, so using it feels like regular Docker:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dso</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>The project is written in Go, open-source under the Apache-2.0 license, and has no commercial component.</p><p><strong>Repository:</strong> <a href="https://github.com/docker-secret-operator/dso" target="_blank" rel="noreferrer">https://github.com/docker-secret-operator/dso</a><br><strong>License:</strong> Apache-2.0<br><strong>Language:</strong> Go</p><h2 id="the-problem" tabindex="-1">The Problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The Problem&quot;">​</a></h2><p>Docker users don&#39;t have a simple, built-in way to manage secrets from cloud providers.</p><p>Docker Swarm has a <code>docker secret</code> command, but most teams aren&#39;t using Swarm anymore. The common alternative — <code>.env</code> files — is a security problem that doesn&#39;t scale. These files sit on disk, get committed to repositories by accident, and make compliance audits painful.</p><p>If you want proper secret management with Docker today, your realistic options are:</p><ol><li>Migrate to Kubernetes (which is often massive overkill for what you need)</li><li>Write custom scripts to pull secrets from cloud APIs before starting containers (fragile, no rotation, no reconciliation)</li><li>Accept the risk and use <code>.env</code> files</li></ol><p>None of these are good answers for the majority of Docker users who just want to run a Compose stack securely.</p><h2 id="how-dso-solves-this" tabindex="-1">How DSO Solves This <a class="header-anchor" href="#how-dso-solves-this" aria-label="Permalink to &quot;How DSO Solves This&quot;">​</a></h2><p>DSO runs as a lightweight systemd service on the Docker host. It:</p><ul><li><strong>Fetches secrets</strong> from cloud providers using machine-level authentication (IAM roles, Managed Identity — no static credentials)</li><li><strong>Injects them</strong> into containers as environment variables or tmpfs mounts (never written to disk)</li><li><strong>Monitors for changes</strong> using a reconciliation loop with SHA-256 hash comparison</li><li><strong>Rotates automatically</strong> — when a secret changes upstream, DSO updates the affected containers with zero manual intervention</li><li><strong>Chooses the right strategy</strong> — it analyzes each container&#39;s characteristics (ports, statefulness, health checks) and picks the safest update approach (rolling, restart, or signal)</li></ul><h2 id="why-a-verified-badge-matters" tabindex="-1">Why a &quot;Verified&quot; Badge Matters <a class="header-anchor" href="#why-a-verified-badge-matters" aria-label="Permalink to &quot;Why a &quot;Verified&quot; Badge Matters&quot;">​</a></h2><p>A Docker Hub &quot;Verified Publisher&quot; badge would help DSO in a few important ways:</p><ol><li><p><strong>Trust signal</strong> — DSO handles secrets. Users need to trust the tool they&#39;re using for security-critical infrastructure. A verified badge from Docker signals that the project meets a quality bar.</p></li><li><p><strong>Visibility</strong> — Most Docker users discover tools through Docker Hub. Being verified and visible there means reaching the teams who actually have this problem.</p></li><li><p><strong>Community confidence</strong> — We&#39;re a small project asking people to trust us with their cloud credentials. Having Docker&#39;s endorsement helps bridge that initial trust gap.</p></li></ol><h2 id="open-source-commitment" tabindex="-1">Open Source Commitment <a class="header-anchor" href="#open-source-commitment" aria-label="Permalink to &quot;Open Source Commitment&quot;">​</a></h2><p>DSO is fully open-source and non-commercial:</p><ul><li><strong>License:</strong> Apache-2.0</li><li><strong>No paid tier or enterprise edition</strong> — Everything is in the public repo</li><li><strong>No telemetry or tracking</strong> — The agent doesn&#39;t phone home</li><li><strong>No vendor lock-in</strong> — Supports multiple cloud providers, and adding new ones is straightforward</li></ul><p>The project is maintained by individual contributors, not backed by a company.</p><h2 id="cncf-sandbox" tabindex="-1">CNCF Sandbox <a class="header-anchor" href="#cncf-sandbox" aria-label="Permalink to &quot;CNCF Sandbox&quot;">​</a></h2><p>We&#39;re targeting CNCF Sandbox admission in 2026. DSO follows the same reconciliation pattern used by Kubernetes controllers — desired state vs actual state, continuously converged — but applies it to Docker environments. We believe this makes it a natural fit for the cloud-native ecosystem.</p><p>Having both CNCF Sandbox status and Docker&#39;s Verified badge would position DSO as a trusted, neutral tool in the secret management space — not tied to any single vendor or platform.</p><h2 id="project-stats" tabindex="-1">Project Stats <a class="header-anchor" href="#project-stats" aria-label="Permalink to &quot;Project Stats&quot;">​</a></h2><ul><li><strong>3 major versions</strong> released (v1, v2, v3)</li><li><strong>4 cloud providers</strong> supported (AWS, Azure, Vault, Huawei)</li><li><strong>Go</strong> — minimal runtime dependencies, ~20MB memory footprint</li><li><strong>Active CI/CD</strong> with security scanning (gosec, govulncheck)</li><li><strong>Documentation site</strong> built with VitePress</li></ul><h2 id="maintainer" tabindex="-1">Maintainer <a class="header-anchor" href="#maintainer" aria-label="Permalink to &quot;Maintainer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>GitHub</th><th>Contact</th></tr></thead><tbody><tr><td>Umair</td><td><a href="https://github.com/umairmd385" target="_blank" rel="noreferrer">@umairmd385</a></td><td><a href="mailto:umairmd385@gmail.com" target="_blank" rel="noreferrer">umairmd385@gmail.com</a></td></tr></tbody></table>',33)])])}const m=t(i,[["render",s]]);export{u as __pageData,m as default};
